const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Point([-112.4685, 34.5400]); // Prescott, Arizona
  const startDate = '2017-06-01';
  const endDate = '2017-06-30';

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .select('temperature_2m')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No ERA5-Land data found for June 2017 in Prescott, Arizona.");
    console.log("C1");
    return;
  }

  // Function to convert Kelvin to Fahrenheit
  const kelvinToFahrenheit = function(image) {
    return image.expression(
      '(K - 273.15) * 1.8 + 32', {
        'K': image.select('temperature_2m')
      }).rename('temperature_F');
  };

  // Apply conversion to the collection
  collection = collection.map(kelvinToFahrenheit);

  // Get the maximum temperature over the entire period
  // We'll compute the max over all images first to get the daily max, then the overall max.
  const maxTempImage = collection.reduce(ee.Reducer.max());

  // 3. Processing & Calculation
  // Reduce the maximum temperature image to a single value for the geometry
  // Use a reasonable scale like 1000m to avoid memory issues for point
  const maxTemperatureFahrenheit = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('temperature_F_max').getInfo(); // Note: band name becomes original_band_reducer_name

  // 4. Validation & Final Answer
  if (maxTemperatureFahrenheit === null || isNaN(maxTemperatureFahrenheit)) {
    console.log("Calculation failed: Max temperature is null or NaN.");
    console.log("C3");
    return;
  }

  console.log(`ERA5-Land Images: ${collectionSize}`);
  console.log(`Max temperature in June 2017: ${maxTemperatureFahrenheit.toFixed(2)} °F`);

  if (maxTemperatureFahrenheit > 100) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
